// IDs are randomly generated by the Broker. Limit the alphabet before using
// an ID as a path segment or delivering it to the OS protocol handler.
export function isRequestId(value) {
  return typeof value === 'string' && /^[A-Za-z0-9_-]{22,128}$/.test(value);
}

export function approvalLink(id) {
  if (!isRequestId(id)) throw new TypeError('Invalid Countersign request ID');
  return `countersign://approve/${id}`;
}
